#!/usr/bin/env node
// Generated by ajch_agent_framework 0.2.0. Edit the source named in .claude/kit.lock.json, then npm run kit.
/**
 * check-docs.mjs — enforce the docs-standard skill on docs/*.md.
 * Shipped by ajch_agent_framework; rendered into each vertical as scripts/check-docs.mjs.
 *
 * Fails (exit 1) on: bad file names, heading structure, numbered docs missing
 * from README, broken relative links or anchors, leftover export placeholders,
 * Mermaid blocks, diagram images without alt text or caption, and SVGs in
 * docs/diagrams/ that lack a source, title, desc or viewBox, carry scripts or
 * external references, or are not embedded. --quiet prints only failures.
 */
import { readdirSync, readFileSync, existsSync } from 'fs';
import { join, dirname, basename } from 'path';
import { fileURLToPath } from 'url';

const ROOT = process.env.KIT_ROOT || join(dirname(fileURLToPath(import.meta.url)), '..');
const DOCS = join(ROOT, 'docs');
const quiet = process.argv.includes('--quiet');
if (!existsSync(DOCS)) { if (!quiet) console.log('docs: no docs/ folder'); process.exit(0); }

const errors = [];
const embedded = new Set();
const files = readdirSync(DOCS).filter((f) => f.endsWith('.md'));

// GitHub heading slug: lowercase, drop punctuation except - and space, spaces to -.
const slug = (h) => h.trim().toLowerCase().replace(/[`*_~]/g, '').replace(/[^\p{L}\p{N}\- ]/gu, '').replace(/ /g, '-');

const anchors = new Map();
const parsed = new Map();
for (const f of files) {
  const text = readFileSync(join(DOCS, f), 'utf-8').replace(/\r\n/g, '\n');
  const lines = text.split('\n');
  // Mask fenced code so headings and links inside it are ignored.
  let fence = false;
  const prose = lines.map((l) => { if (/^\s*```/.test(l)) { fence = !fence; return ''; } return fence ? '' : l; });
  const seen = new Map();
  const ids = new Set();
  for (const l of prose) {
    const m = l.match(/^(#{1,6})\s+(.*)$/);
    if (!m) continue;
    const base = slug(m[2]);
    const n = seen.get(base) ?? 0;
    seen.set(base, n + 1);
    ids.add(n ? `${base}-${n}` : base);
  }
  anchors.set(f, ids);
  parsed.set(f, { text, lines, prose });
}

for (const f of files) {
  const { text, lines, prose } = parsed.get(f);
  const err = (msg, i) => errors.push(`${f}${i !== undefined ? ':' + (i + 1) : ''}: ${msg}`);

  if (f !== 'README.md' && !/^\d\d-[a-z0-9]+(-[a-z0-9]+)*\.md$/.test(f)) err('file name must be README.md or NN-kebab-case.md');

  const heads = prose.map((l, i) => [l.match(/^(#{1,6})\s/), i]).filter(([m]) => m).map(([m, i]) => [m[1].length, i]);
  const h1 = heads.filter(([d]) => d === 1);
  if (h1.length !== 1) err(`needs exactly one # heading, found ${h1.length}`);
  for (let k = 1; k < heads.length; k++) if (heads[k][0] > heads[k - 1][0] + 1) err(`heading jumps from h${heads[k - 1][0]} to h${heads[k][0]}`, heads[k][1]);

  if (/embedded content|&#91;/i.test(text)) err('export placeholder left in (embedded content / &#91;)');

  prose.forEach((l, i) => {
    for (const [, target] of l.matchAll(/\]\(([^)\s]+)(?:\s+"[^"]*")?\)/g)) {
      if (/^(https?:|mailto:)/.test(target)) continue;
      const [path, hash] = target.split('#');
      const file = path ? join(DOCS, path) : join(DOCS, f);
      if (path && !existsSync(file)) { err(`broken link: ${target}`, i); continue; }
      if (hash && basename(file).endsWith('.md') && dirname(file) === DOCS && !anchors.get(basename(file))?.has(hash)) err(`broken anchor: ${target}`, i);
    }
  });

  lines.forEach((l, i) => { if (/^\s*```mermaid\s*$/.test(l)) err('Mermaid block: draw it as an SVG diagram (svg-diagram-craft)', i); });

  prose.forEach((l, i) => {
    for (const m of l.matchAll(/!\[([^\]]*)\]\((diagrams\/[^)\s]+\.svg)\)/g)) {
      embedded.add(basename(m[2]));
      if (!m[1].trim()) err(`diagram ${m[2]} has no alt text`, i);
      const next = lines.slice(i + 1).find((x) => x.trim());
      if (!next || !/^\s*[*_][^*_].*[*_]\s*$/.test(next)) err(`diagram ${m[2]} needs an italic caption line directly under it`, i);
    }
  });
}

const DIAGRAMS = join(DOCS, 'diagrams');
if (existsSync(DIAGRAMS)) {
  for (const f of readdirSync(DIAGRAMS).filter((x) => x.endsWith('.svg'))) {
    const svg = readFileSync(join(DIAGRAMS, f), 'utf-8');
    const err = (msg) => errors.push(`diagrams/${f}: ${msg}`);
    if (!existsSync(join(DIAGRAMS, 'src', f.replace(/\.svg$/, '.mjs')))) err('no source in docs/diagrams/src/');
    if (!/<title[ >]/.test(svg) || !/<desc[ >]/.test(svg)) err('needs <title> and <desc>');
    if (!/viewBox="/.test(svg)) err('needs a viewBox');
    if (/<script|<foreignObject|\bon[a-z]+="/i.test(svg)) err('scripts, event handlers and foreignObject are not allowed');
    if (/(href|src)="(https?:)?\/\//i.test(svg) || /url\((['"]?)https?:/i.test(svg)) err('external references are not allowed');
    if (!embedded.has(f)) err('not embedded in any doc');
  }
}

if (files.includes('README.md')) {
  const readme = parsed.get('README.md').text;
  for (const f of files.filter((x) => /^\d\d-/.test(x))) if (!readme.includes(`(${f}`)) errors.push(`README.md: does not link ${f}`);
} else if (files.length) errors.push('docs/README.md is missing');

if (errors.length) {
  console.error(`docs: ${errors.length} problem(s)\n` + errors.map((e) => '  ' + e).join('\n'));
  process.exit(1);
}
if (!quiet) console.log(`docs: ${files.length} file(s) clean`);
